import math

def _rendezvous_slot_intervals(sandbox):
    return sandbox.get_rendezvous_slots()

def build_agent(sandbox):
    return sandbox.get_seeker_body()

def agent_action(sandbox, agent_body, step_count):
    # Initialize state if not already done
    if not hasattr(agent_body, '_state'):
        agent_body._state = {
            'last_tx': 0.0, 'last_ty': 0.0,
            'tvx': 0.0, 'tvy': 0.0,
            'cooldown_timer': 0,
            'last_cooldown_step': 0
        }
    state = agent_body._state
    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()
    angle = sandbox.get_seeker_heading()
    x_min, x_max = sandbox.get_corridor_bounds()
    remaining_budget = sandbox.get_remaining_impulse_budget()

    # Estimate target velocity using position history
    if step_count % 5 == 0 and step_count > 5:
        dt = 5.0 / 60.0
        state['tvx'] = 0.5 * state['tvx'] + 0.5 * (tx - state['last_tx']) / dt
        state['tvy'] = 0.5 * state['tvy'] + 0.5 * (ty - state['last_ty']) / dt
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty

    # Determine if in a rendezvous slot
    slots = _rendezvous_slot_intervals(sandbox)
    in_slot = any(lo <= step_count <= hi for (lo, hi) in slots)

    # Determine target position for guidance
    if step_count < 110:
        gx, gy = 11.95, 1.35
    elif in_slot:
        gx, gy = tx, ty
    else:
        # Default to corridor center if not in slot
        gx = (x_min + x_max) / 2
        gy = 1.35

    # Calculate desired heading direction
    target_dir = math.atan2(ty - sy, tx - sx)
    if in_slot:
        # When in slot, align heading with target velocity if speed is sufficient
        if abs(state['tvx']) > 0.15 or abs(state['tvy']) > 0.15:
            desired_heading = math.atan2(state['tvy'], state['tvx'])
        else:
            desired_heading = target_dir
    else:
        desired_heading = target_dir

    # Calculate heading error and rotation command
    heading_error = desired_heading - angle
    if heading_error > math.pi:
        heading_error -= 2 * math.pi
    elif heading_error < -math.pi:
        heading_error += 2 * math.pi
    heading_rotation = min(0.12, max(-0.12, heading_error))

    # Calculate force to align heading
    heading_force = 20.0 * heading_rotation

    # Calculate position error
    pos_error = math.hypot(tx - sx, ty - sy)

    # Adjust force based on rendezvous slot
    if in_slot:
        # In slot: prioritize relative speed and heading alignment
        if pos_error < 6.0:
            # Close enough to target, reduce speed
            if abs(svx) > 0.5:
                force_x = -20.0 * svx
            else:
                force_x = 0.0
            if abs(svy) > 0.5:
                force_y = -20.0 * svy
            else:
                force_y = 0.0
        else:
            # Still distant, approach target
            force_x = 100.0 * (tx - sx)
            force_y = 100.0 * (ty - sy)
    else:
        # Not in slot: approach corridor center
        force_x = 100.0 * (gx - sx)
        force_y = 100.0 * (gy - sy)

    # Combine heading and position forces
    total_force_x = force_x + heading_force
    total_force_y = force_y

    # Apply thrust cooldown check
    if step_count > state['last_cooldown_step']:
        # Check if thrust is in cooldown
        if state['cooldown_timer'] > 0:
            state['cooldown_timer'] -= 1
            # Apply reduced thrust
            max_thrust = 20.0
        else:
            # Check if previous thrust exceeded 90 N
            # (Assume previous thrust was 90 N for cooldown trigger)
            # For simplicity, assume thrust is capped at 90 N
            max_thrust = 90.0
            state['last_cooldown_step'] = step_count
    else:
        max_thrust = 90.0

    # Calculate magnitude of total force
    mag = math.hypot(total_force_x, total_force_y)

    # Normalize force vector and apply thrust limit
    if mag > 0:
        fx = (total_force_x / mag) * max_thrust
        fy = (total_force_y / mag) * max_thrust
    else:
        fx = 0.0
        fy = 0.0

    # Apply force with budget check
    if remaining_budget > 0:
        sandbox.apply_seeker_force(fx, fy)
    else:
        # No fuel left, stop thrust
        sandbox.apply_seeker_force(0.0, 0.0)
